local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_GREET, 'LONG LIVE KING TIBIANUS! Welcome to the isle of Edron!')
npcHandler:setMessage(MESSAGE_FAREWELL, 'LONG LIVE THE KING!')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'LONG LIVE THE KING!')
keywordHandler:addKeyword({'castle'}, StdModule.say, {npcHandler = npcHandler, text = 'The Edron castle is the home of many shops, a tavern, a bank, a depot, a post office and the temple of Banor\'s blood.'})
keywordHandler:addKeyword({'work'}, StdModule.say, {npcHandler = npcHandler, text = 'Explore the isle and destroy any enemy forces encountered. The honor shall be your reward.'})
keywordHandler:addKeyword({'tyrant'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'post'}, StdModule.say, {npcHandler = npcHandler, text = 'The post office, run by the lovely Chrystal is in the southwest corner of the castle, near the Royal Bank.'})
keywordHandler:addKeyword({'news'}, StdModule.say, {npcHandler = npcHandler, text = 'Sorry, that\'s confidential.'})
keywordHandler:addKeyword({'bank'}, StdModule.say, {npcHandler = npcHandler, text = 'You\'ll find the bank in the southwest of the castle. Look for Ebenizer, you can\'t miss him.'})
keywordHandler:addKeyword({'sell'}, StdModule.say, {npcHandler = npcHandler, text = 'Visit the shopkeepers to buy their fine wares.'})
keywordHandler:addKeyword({'north'}, StdModule.say, {npcHandler = npcHandler, text = 'In the north, there is an ancient city of cyclopses, called the cyclopolis. They are wary of us, but trade with servants of evil from any known race.'})
keywordHandler:addKeyword({'fuck'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'temple'}, StdModule.say, {npcHandler = npcHandler, text = 'The temple can be found underground, in the southeast corner of the castle. There you can become a citizen of Edron'})
keywordHandler:addKeyword({'king'}, StdModule.say, {npcHandler = npcHandler, text = 'LONG LIVE THE KING!'})
keywordHandler:addKeyword({'west'}, StdModule.say, {npcHandler = npcHandler, text = 'There are rumours of two tribes of minor monsters who battle each other for dominance over the area. Not worth to crawl the sewers to get there.'})
keywordHandler:addKeyword({'city'}, StdModule.say, {npcHandler = npcHandler, text = 'In the city there is a furniture store and a jeweller. The Noodles Academy and the cemetary are outside.'})
keywordHandler:addKeyword({'Edron'}, StdModule.say, {npcHandler = npcHandler, text = 'The mysterious isle has many secrets and sights outside the castle. The areas of interest are in the west, the southwest, the north, and the northwest.'})
keywordHandler:addKeyword({'shit'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'lunatic'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'shop'}, StdModule.say, {npcHandler = npcHandler, text = 'The shops are on the eastern side of the castle. Upstairs you\'ll find a tailor, a blacksmith, and an equipment store.'})
keywordHandler:addKeyword({'subject'}, StdModule.say, {npcHandler = npcHandler, text = 'We all live under the benevolent guidance of our king.'})
keywordHandler:addKeyword({'asshole'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'battlegroup'}, StdModule.say, {npcHandler = npcHandler, text = 'There are the Dogs of War, the Red Guards, and the Silver Guards.'})
keywordHandler:addKeyword({'army'}, StdModule.say, {npcHandler = npcHandler, text = 'The local army consists only of the Knights of Banor\'s Blood.'})
keywordHandler:addKeyword({'southwest'}, StdModule.say, {npcHandler = npcHandler, text = 'There are rumours of orc buildings in the southeast. They say some daring fellows found a passage to this area in an old cavern beneath the Edron flats.'})
keywordHandler:addKeyword({'idiot'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'cemetary'}, StdModule.say, {npcHandler = npcHandler, text = 'The cemetary is north of the hamlet of Stonehome, which is at the east coast, northeast of Edron city. The cemetary is rumoured to be haunted.'})
keywordHandler:addKeyword({'stupid'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'tavern'}, StdModule.say, {npcHandler = npcHandler, text = 'The tavern is called the Horn of Plenty, and it\'s located upstairs in the southwest corner of the castle.'})
keywordHandler:addKeyword({'northwest'}, StdModule.say, {npcHandler = npcHandler, text = 'Don\'t even think about going there. Renegade Knights of Banor\'s Blood went there to unearth forbidden secrets in an ancient ruin.'})
keywordHandler:addKeyword({'academy'}, StdModule.say, {npcHandler = npcHandler, text = 'The Noodles Academy of the magic arts is in the east of Edron city.'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'I\'m the Edron harbour guard. I protect Edron castle and inform visitors about this building and Edron itself.'})
keywordHandler:addKeyword({'name'}, StdModule.say, {npcHandler = npcHandler, text = 'I\'m Lieutenant Falk.'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)

local focusModule = FocusModule:new()
focusModule:addGreetMessage('hi')
focusModule:addGreetMessage('hello')
npcHandler:addModule(focusModule)

